/* v0.2 proposed class branches (doc 04 section 18.3), generated by tools_manual/write_branches.py: kept
   separate from the pipeline. proposed_branch(Node, Class): at Node, a program whose root functions satisfy
   Class's relation (prolog/class_specs.pl) on every battery input is a new version of Class.
     proposed_main -- Facts : reads file_node/1 and holds/1, prints PROPOSED|Node|Class
   A branch at Node also covers the nodes below it (a variation in its family), never the nodes above.
*/
:- dynamic file_node/1, holds/1.

proposed_main :- current_prolog_flag(argv, [Facts|_]), load_files(Facts, [if(true)]),
    forall(distinct(M-C, applies(M, C)), format('PROPOSED|~w|~w~n', [M, C])).
applies(M, C) :- proposed_branch(M, C), file_node(N), under_or_at(N, M).
under_or_at(N, M) :- N == M, !.
under_or_at(N, M) :- atom_concat(M, '>', P), sub_atom(N, 0, _, _, P).
class_holds(C) :- holds(C).

proposed_branch('numeric>recurrence>double_recursion', power) :- class_holds(power).   % from divide_and_conquer/power.py
proposed_branch('numeric>recurrence>modulo_recurrence', gcd) :- class_holds(gcd).   % from maths/greatest_common_divisor.py
proposed_branch('sequence_query>target_search>interval_halving', sorting) :- class_holds(sorting).   % from sorts/merge_insertion_sort.py, sorts/tim_sort.py
proposed_branch('sequence_query>target_search>linear_scan', search) :- class_holds(search).   % from searches/double_linear_search.py
proposed_branch('sequence_transformation>comparison_sort', sorting) :- class_holds(sorting).   % from sorts/adaptive_merge_sort.py, sorts/exchange_sort.py, sorts/pigeon_sort.py, sorts/recursive_insertion_sort.py, sorts/shell_sort.py
proposed_branch('sequence_transformation>comparison_sort>adjacent_exchange', sorting) :- class_holds(sorting).   % from sorts/bubble_sort.py, sorts/bubble_sort_recursive.py, sorts/cocktail_shaker_sort.py, sorts/double_sort.py, sorts/gnome_sort.py, sorts/odd_even_sort.py, sorts/odd_even_transposition_single_threaded.py
proposed_branch('sequence_transformation>comparison_sort>gap_exchange', sorting) :- class_holds(sorting).   % from sorts/comb_sort.py, sorts/shrink_shell_sort.py
proposed_branch('sequence_transformation>comparison_sort>heap', sorting) :- class_holds(sorting).   % from sorts/heap_sort.py
proposed_branch('sequence_transformation>comparison_sort>merge', sorting) :- class_holds(sorting).   % from divide_and_conquer/mergesort.py
proposed_branch('sequence_transformation>comparison_sort>partition_recursive', sorting) :- class_holds(sorting).   % from sorts/circle_sort.py, sorts/quick_sort.py, sorts/recursive_quick_sort.py
proposed_branch('sequence_transformation>comparison_sort>prefix_reversal', sorting) :- class_holds(sorting).   % from sorts/reverse_selection.py
proposed_branch('sequence_transformation>comparison_sort>select_extreme', sorting) :- class_holds(sorting).   % from sorts/selection_sort.py
proposed_branch('sequence_transformation>comparison_sort>shift_insertion', sorting) :- class_holds(sorting).   % from sorts/insertion_sort.py
proposed_branch('sequence_transformation>comparison_sort>stooge_recursion', sorting) :- class_holds(sorting).   % from sorts/stooge_sort.py
proposed_branch('sequence_transformation>distribution_sort>histogram', sorting) :- class_holds(sorting).   % from sorts/pigeonhole_sort.py
proposed_branch('sequence_transformation>uncompared_rearrangement', sorting) :- class_holds(sorting).   % from sorts/reverse_selection.py
